const axios = require('axios');
const _LLAMA_URL = (() => { try { return ($env.OLLAMA_URL || 'http://llama-3090:11434').replace(/\/$/, ''); } catch(e) { return 'http://llama-3090:11434'; } })();
const _LLAMA_KEY = (() => { try { return $env.OLLAMA_API_KEY || ''; } catch(e) { return ''; } })();
function _llamaHeaders() { const h = { 'Content-Type': 'application/json' }; if (_LLAMA_KEY) h['Authorization'] = 'Bearer ' + _LLAMA_KEY; return h; }
// PROJ-99 shim: takes an OLD Ollama /api/generate body, calls llama.cpp /v1/chat/completions, returns a { data: { response } } shaped result.
async function llamaGenerate(body, cfg) {
  const opts = body.options || {};
  const payload = { model: body.model, messages: [{ role: 'user', content: body.prompt }], stream: false };
  if (opts.temperature !== undefined) payload.temperature = opts.temperature;
  if (opts.num_predict !== undefined) payload.max_tokens = opts.num_predict;
  if (body.format === 'json') payload.response_format = { type: 'json_object' };
  const rcfg = Object.assign({}, cfg || {}, { headers: Object.assign({}, _llamaHeaders(), (cfg && cfg.headers) || {}) });
  const resp = await axios.post(_LLAMA_URL + '/v1/chat/completions', payload, rcfg);
  const content = (((resp.data || {}).choices || [{}])[0].message || {}).content || '';
  return { data: { response: content }, status: resp.status, statusText: resp.statusText };
}
const item = $input.first().json;
const plaintext = (item.plaintext || '').slice(0, 20000);
const validTypes = ['Invoice', 'BankStatement', 'Document', 'Email', 'SecuritySettlement', 'Contract'];
let ollamaModel = 'qwen3.5:27b-q4_K_M'; try { ollamaModel = $env.OLLAMA_MODEL_DMS || 'qwen3:14b'; } catch(e) {}
let threshold = 0.7; try { const t = parseFloat($env.DMS_CLASSIFICATION_CONFIDENCE_THRESHOLD); if (!isNaN(t)) threshold = t; } catch(e) {}

const PROMPT_HEADER = 'You are a document classifier. Analyze the following document text and determine the document type.\nChoose EXACTLY ONE of the following types, using these distinguishing features as guidance:\n- Invoice: contains an invoice number, gross/net amount, VAT rate, due date, itemized line items\n- BankStatement: contains an IBAN, opening/closing balance, a list of individual transactions/bookings, statement period\n- SecuritySettlement: contains an ISIN, depot number, security name, buy/sell/dividend transaction type, quantity and price\n- Contract: contains contract parties, sign date, start/end date, notice period, recurring (monthly/annual) cost\n- Email: has email-style headers (From/To/Subject/Date) and/or a salutation and signature typical of email correspondence\n- Document: generic correspondence, forms, certificates or notices that do not match any of the above\n\nRespond ONLY with a JSON object: {"document_type": "<Type>", "confidence": <0-1>}\n"confidence" is your own certainty that the chosen type is correct, as a number between 0 and 1.\n\nDocument text:\n' + plaintext;

function tryParse(responseStr) {
  const parsed = JSON.parse(responseStr);
  if (!validTypes.includes(parsed.document_type)) return null;
  let confidence = parseFloat(parsed.confidence);
  if (isNaN(confidence)) confidence = 0;
  confidence = Math.max(0, Math.min(1, confidence));
  return { document_type: parsed.document_type, confidence };
}

async function callOllama(temperature) {
  const resp = await llamaGenerate( {
    model: ollamaModel,
    prompt: PROMPT_HEADER,
    stream: false,
    format: 'json',
    options: { temperature, num_predict: 500 }
  }, { timeout: 120000 });
  return resp.data.response || '';
}

// Attempt 1 (temperature 0, deterministic) + existing parse-error retry safety net (same prompt, unchanged behavior)
let attempt1 = null;
let retried = false;
let retryFailed = false;
try {
  const raw1 = await callOllama(0);
  attempt1 = tryParse(raw1);
  if (!attempt1) throw new Error('invalid document_type in response');
} catch(e) {
  retried = true;
  try {
    const raw1b = await callOllama(0);
    attempt1 = tryParse(raw1b);
    if (!attempt1) retryFailed = true;
  } catch(e2) {
    retryFailed = true;
  }
}
if (!attempt1) attempt1 = { document_type: 'Document', confidence: 0 };

// Attempt 2 (temperature 0.3, same extended prompt) only if attempt1 confidence is below threshold
let secondAttemptUsed = false;
let winner = attempt1;
if (attempt1.confidence < threshold) {
  secondAttemptUsed = true;
  try {
    const raw2 = await callOllama(0.3);
    const attempt2 = tryParse(raw2);
    // Higher confidence wins; tie goes to the 2nd (informed) attempt
    if (attempt2 && attempt2.confidence >= attempt1.confidence) {
      winner = attempt2;
    }
  } catch(e) {
    // 2nd attempt failed outright — keep attempt 1's best guess
  }
}

const uncertain = winner.confidence < threshold;

const result = { document_type: winner.document_type, confidence: winner.confidence, uncertain: uncertain, classification_retried: retried, classification_retry_failed: retryFailed, second_attempt_used: secondAttemptUsed };
return [{ json: result }];
